package com.fitmind.service;
import com.fitmind.entity.*; import com.fitmind.vo.DashboardOverviewVO; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.math.*; import java.util.*;
@Service @RequiredArgsConstructor public class DashboardService { private final ProfileService profileService; private final WeightService weightService; private final HealthLetterService healthLetterService; public DashboardOverviewVO overview(){UserProfile p=profileService.get();List<WeightRecord> trend=weightService.trend(7);WeightRecord latest=trend.isEmpty()?null:trend.get(trend.size()-1);BigDecimal current=latest==null?p.getStartWeightKg():latest.getWeightKg();BigDecimal change=trend.size()<2?BigDecimal.ZERO:current.subtract(trend.get(0).getWeightKg());BigDecimal denominator=p.getStartWeightKg().subtract(p.getTargetWeightKg());BigDecimal progress=denominator.signum()==0?BigDecimal.ZERO:p.getStartWeightKg().subtract(current).multiply(BigDecimal.valueOf(100)).divide(denominator,1,RoundingMode.HALF_UP);progress=progress.max(BigDecimal.ZERO).min(BigDecimal.valueOf(100));DashboardOverviewVO v=new DashboardOverviewVO();v.setCurrentWeightKg(current);v.setStartWeightKg(p.getStartWeightKg());v.setTargetWeightKg(p.getTargetWeightKg());v.setDistanceToTargetKg(current.subtract(p.getTargetWeightKg()).max(BigDecimal.ZERO));v.setChange7dKg(change);v.setProgressPercent(progress);v.setPreferredWeightUnit(p.getPreferredWeightUnit());v.setWeightTrend(trend);v.setTodayHealthLetter(healthLetterService.findToday());return v;} }
